//! Compact portable schematic codec. States are stored as registry strings,
//! never process-local IDs, so files survive server restarts.
use std::collections::HashMap;
use crate::clipboard::Clipboard;
use crate::math::BlockVector3;
use crate::registry::BlockStateRegistry;

const MAGIC_V1:&[u8;8]=b"FAWEBIM1";const MAGIC_V2:&[u8;8]=b"FAWEBIM2";const MAGIC_V3:&[u8;8]=b"FAWEBIM3";
fn checksum(data:&[u8])->u64{data.iter().fold(0xcbf29ce484222325u64,|h,b|(h^*b as u64).wrapping_mul(0x100000001b3))}
pub fn encode(clip:&Clipboard,reg:&dyn BlockStateRegistry)->Result<Vec<u8>,String>{let mut palette=Vec::<String>::new();let mut ids=HashMap::<i32,u32>::new();let mut cells=Vec::new();clip.for_each(|x,y,z,state|{let idx=*ids.entry(state).or_insert_with(||{let i=palette.len()as u32;palette.push(reg.describe(state));i});cells.push((x,y,z,idx));});let mut out=MAGIC_V3.to_vec();for v in [clip.size().x,clip.size().y,clip.size().z,clip.origin().x,clip.origin().y,clip.origin().z]{out.extend_from_slice(&v.to_le_bytes());}put_u32(&mut out,palette.len()as u32);for s in palette{put_u32(&mut out,s.len()as u32);out.extend_from_slice(s.as_bytes());}put_u32(&mut out,cells.len()as u32);let size=clip.size();for(x,y,z,p)in cells{let index=(y as u32)*(size.z as u32)*(size.x as u32)+(z as u32)*(size.x as u32)+x as u32;put_u32(&mut out,index);put_u32(&mut out,p);}if out.len()>64<<20{return Err("schematic exceeds 64 MiB".into());}let digest=checksum(&out);out.extend_from_slice(&digest.to_le_bytes());Ok(out)}
pub fn decode(data:&[u8],reg:&dyn BlockStateRegistry)->Result<Clipboard,String>{if data.len()>64<<20{return Err("schematic exceeds 64 MiB".into());}if data.len()<8{return Err("truncated schematic".into());}let version=&data[..8];let indexed=version==MAGIC_V3;let body=if version==MAGIC_V2||version==MAGIC_V3{if data.len()<16{return Err("truncated schematic checksum".into());}let end=data.len()-8;let expected=u64::from_le_bytes(data[end..].try_into().unwrap());if checksum(&data[..end])!=expected{return Err("schematic checksum mismatch".into());}&data[..end]}else if version==MAGIC_V1{data}else{return Err("not a FAWE-BIM schematic".into());};let mut r=Reader{data:body,pos:0};r.take(8)?;let size=BlockVector3::at(r.i32()?,r.i32()?,r.i32()?);let origin=BlockVector3::at(r.i32()?,r.i32()?,r.i32()?);if size.x<=0||size.y<=0||size.z<=0{return Err("invalid schematic dimensions".into());}let volume=(size.x as usize).checked_mul(size.y as usize).and_then(|v|v.checked_mul(size.z as usize)).ok_or("schematic is too large")?;if volume>2_000_000{return Err("schematic exceeds the block limit".into());}let pn=r.u32()? as usize;if pn==0{return Err("schematic palette is empty".into());}if pn>65536{return Err("schematic palette is too large".into());}let mut palette=Vec::with_capacity(pn);for _ in 0..pn{let n=r.u32()? as usize;if n==0||n>65536{return Err("invalid schematic state length".into());}let s=std::str::from_utf8(r.take(n)?).map_err(|_|"invalid UTF-8 state")?;let state=reg.parse(s);if state<0{return Err(format!("unknown block state '{s}'"));}palette.push(state);}let count=r.u32()? as usize;if count>volume{return Err("too many schematic cells".into());}let mut blocks=vec![-1;volume];let mut seen=vec![false;volume];for _ in 0..count{let(i,p)=if indexed{(r.u32()? as usize,r.u32()? as usize)}else{let(x,y,z,p)=(r.i32()?,r.i32()?,r.i32()?,r.u32()? as usize);if x<0||y<0||z<0||x>=size.x||y>=size.y||z>=size.z{return Err("invalid schematic cell".into());}((y*size.z*size.x+z*size.x+x)as usize,p)};if i>=volume||p>=palette.len(){return Err("invalid schematic cell".into());}if seen[i]{return Err("duplicate schematic cell".into());}seen[i]=true;blocks[i]=palette[p];}if r.pos!=body.len(){return Err("trailing schematic data".into());}Ok(Clipboard::from_parts(size,origin,blocks))}
fn put_u32(out:&mut Vec<u8>,v:u32){out.extend_from_slice(&v.to_le_bytes());}struct Reader<'a>{data:&'a[u8],pos:usize}impl<'a>Reader<'a>{fn take(&mut self,n:usize)->Result<&'a[u8],String>{let end=self.pos.checked_add(n).ok_or("truncated schematic")?;let s=self.data.get(self.pos..end).ok_or("truncated schematic")?;self.pos=end;Ok(s)}fn u32(&mut self)->Result<u32,String>{Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))}fn i32(&mut self)->Result<i32,String>{Ok(i32::from_le_bytes(self.take(4)?.try_into().unwrap()))}}
#[cfg(test)]mod tests{use super::*;use crate::region::{CuboidRegion,RegionShape};use crate::world::{Extent,InMemoryWorld};use crate::registry::InMemoryBlockRegistry;#[test]fn round_trip_is_portable_and_rejects_damage(){let reg=InMemoryBlockRegistry::with_vanilla_subset();let mut w=InMemoryWorld::default();w.set_block(2,3,4,reg.parse("stone"));let mut region=RegionShape::Cuboid(CuboidRegion::new(BlockVector3::at(2,3,4),BlockVector3::at(2,3,4)));let c=Clipboard::capture(&w,&mut region);let bytes=encode(&c,&reg).unwrap();let d=decode(&bytes,&reg).unwrap();assert_eq!(d.origin(),c.origin());assert_eq!(d.get(0,0,0),reg.parse("stone"));assert!(decode(&bytes[..10],&reg).is_err());let mut damaged=bytes.clone();damaged[12]^=1;assert!(decode(&damaged,&reg).unwrap_err().contains("checksum"));let mut legacy=MAGIC_V1.to_vec();for v in [1i32,1,1,0,0,0]{legacy.extend_from_slice(&v.to_le_bytes());}put_u32(&mut legacy,1);put_u32(&mut legacy,5);legacy.extend_from_slice(b"stone");put_u32(&mut legacy,1);for v in [0i32,0,0]{legacy.extend_from_slice(&v.to_le_bytes());}put_u32(&mut legacy,0);assert_eq!(decode(&legacy,&reg).unwrap().get(0,0,0),reg.parse("stone"));let mut v2=legacy.clone();v2[..8].copy_from_slice(MAGIC_V2);let digest=checksum(&v2);v2.extend_from_slice(&digest.to_le_bytes());assert_eq!(decode(&v2,&reg).unwrap().get(0,0,0),reg.parse("stone"));let mut duplicate=MAGIC_V1.to_vec();for v in [2i32,1,1,0,0,0]{duplicate.extend_from_slice(&v.to_le_bytes());}put_u32(&mut duplicate,1);put_u32(&mut duplicate,5);duplicate.extend_from_slice(b"stone");put_u32(&mut duplicate,2);for _ in 0..2{for v in [0i32,0,0]{duplicate.extend_from_slice(&v.to_le_bytes());}put_u32(&mut duplicate,0);}assert_eq!(decode(&duplicate,&reg).unwrap_err(),"duplicate schematic cell");let sparse=Clipboard::from_parts(BlockVector3::at(2,1,1),BlockVector3::ZERO,vec![reg.parse("stone"),-1]);let restored=decode(&encode(&sparse,&reg).unwrap(),&reg).unwrap();assert_eq!(restored.get(0,0,0),reg.parse("stone"));assert_eq!(restored.get(1,0,0),-1);}}
